use std::sync::Arc;
let a = Arc::new(vec![1, 2, 3]);
let b = Arc::clone(&a);
println!("{} {}", Arc::strong_count(&a), Arc::ptr_eq(&a, &b));

#[derive(Clone, Copy)]
